function Invoke-ControlBinary([string]$Binary,[string]$ConfigPath,[string[]]$Arguments) {
    $process=Start-Child $Arguments $Binary $ConfigPath
    try {$out=$process.StandardOutput.ReadToEndAsync();$err=$process.StandardError.ReadToEndAsync();$process.StandardInput.Close();Assert-True ($process.WaitForExit(120000)) 'Registry producer timeout';$stdout=$out.GetAwaiter().GetResult();$stderr=$err.GetAwaiter().GetResult();$script:Invocation++;Save-Json (Join-Path $script:CaseRoot ('process-{0:D3}.json'-f$script:Invocation)) @{executablePath=$Binary;config=$ConfigPath;arguments=$Arguments;exitCode=$process.ExitCode;stdout=$stdout;stderr=$stderr};return @{ExitCode=$process.ExitCode;Json=($stdout|ConvertFrom-Json -Depth 80);Stdout=$stdout;Stderr=$stderr}}
    finally {if(!$process.HasExited){$process.Kill($true);$process.WaitForExit()};$process.Dispose()}
}
